  const handleDuplicate = async () => {
    if (isDuplicating) return;
    setIsDuplicating(true);
    try {
      const result = await duplicateWebhookAction({ webhookId: webhook.id });
      if (result?.data) {
        toast.success(t("workspace.integrations.webhooks.webhook_duplicate_successfully"));
        router.refresh();
      } else {
        const errorMessage = getFormattedErrorMessage(result);
        toast.error(errorMessage);
      }
    } catch (e) {
      toast.error(e instanceof Error ? e.message : "Unknown error occurred");
    } finally {
